-- CONECTASUCRE | Migracion MySQL -> PostgreSQL 17
-- Estructura completa reconstruida a partir de CSV_EE(1), CSV_EE1 y CSV_EE2.
-- 15 tablas, claves primarias, unicas, foraneas, CHECK, DEFAULT y subtotal generado.
-- IMPORTANTE: ejecutar SOLO en conectasucre_final de PostgreSQL, estando VACIA.
-- Este archivo NO transfiere datos, vistas, procedimientos ni triggers.
-- Esquema original se conserva en MySQL.
BEGIN;

CREATE TABLE public."auditoria_despachos" (
    "id_auditoria" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_despacho" BIGINT NOT NULL,
    "fecha_modificacion" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "usuario_bd" VARCHAR(100) NOT NULL,
    "estado_anterior" VARCHAR(20),
    "estado_nuevo" VARCHAR(20) NOT NULL,
    "observacion" VARCHAR(300),
    CONSTRAINT "pk_auditoria_despachos" PRIMARY KEY ("id_auditoria")
);

CREATE TABLE public."clientes" (
    "id_cliente" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "tipo_documento" VARCHAR(15) NOT NULL,
    "numero_documento" VARCHAR(30) NOT NULL,
    "nombre_comercial" VARCHAR(150) NOT NULL,
    "nombre_contacto" VARCHAR(120),
    "telefono" VARCHAR(25),
    "correo" VARCHAR(120),
    "direccion" VARCHAR(200),
    "id_municipio" BIGINT NOT NULL,
    "fecha_registro" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "estado_cliente" VARCHAR(15) DEFAULT 'ACTIVO' NOT NULL,
    CONSTRAINT "chk_cliente_estado" CHECK ("estado_cliente" in ('ACTIVO','INACTIVO')),
    CONSTRAINT "pk_clientes" PRIMARY KEY ("id_cliente"),
    CONSTRAINT "uk_cliente_documento" UNIQUE ("tipo_documento", "numero_documento")
);

CREATE TABLE public."conductores" (
    "id_conductor" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "tipo_documento" VARCHAR(15) NOT NULL,
    "numero_documento" VARCHAR(30) NOT NULL,
    "nombres" VARCHAR(100) NOT NULL,
    "apellidos" VARCHAR(100) NOT NULL,
    "telefono" VARCHAR(25),
    "numero_licencia" VARCHAR(40) NOT NULL,
    "categoria_licencia" VARCHAR(10) NOT NULL,
    "fecha_vencimiento_licencia" DATE,
    "estado_conductor" VARCHAR(20) DEFAULT 'DISPONIBLE' NOT NULL,
    CONSTRAINT "chk_conductor_estado" CHECK ("estado_conductor" in ('DISPONIBLE','EN_RUTA','INACTIVO')),
    CONSTRAINT "pk_conductores" PRIMARY KEY ("id_conductor"),
    CONSTRAINT "uk_conductor_documento" UNIQUE ("tipo_documento", "numero_documento"),
    CONSTRAINT "uk_conductor_licencia" UNIQUE ("numero_licencia")
);

CREATE TABLE public."despachos_asignaciones" (
    "id_despacho" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_pedido" BIGINT NOT NULL,
    "id_vehiculo" BIGINT NOT NULL,
    "id_conductor" BIGINT NOT NULL,
    "id_ruta" BIGINT NOT NULL,
    "fecha_asignacion" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "fecha_salida" TIMESTAMP WITHOUT TIME ZONE,
    "estado_despacho" VARCHAR(20) DEFAULT 'ASIGNADO' NOT NULL,
    CONSTRAINT "chk_despacho_estado" CHECK ("estado_despacho" in ('ASIGNADO','EN_TRANSITO','ENTREGADO','CANCELADO')),
    CONSTRAINT "pk_despachos_asignaciones" PRIMARY KEY ("id_despacho")
);

CREATE TABLE public."detalle_pedidos" (
    "id_detalle" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_pedido" BIGINT NOT NULL,
    "id_producto" BIGINT NOT NULL,
    "cantidad" NUMERIC(12,3) NOT NULL,
    "precio_unitario" NUMERIC(14,2) NOT NULL,
    "peso_unitario_kg" NUMERIC(10,3) NOT NULL,
    "subtotal" NUMERIC(14,2) GENERATED ALWAYS AS ("cantidad" * "precio_unitario") STORED,
    CONSTRAINT "chk_detalle_cantidad" CHECK ("cantidad" > 0),
    CONSTRAINT "chk_detalle_peso" CHECK ("peso_unitario_kg" > 0),
    CONSTRAINT "chk_detalle_precio" CHECK ("precio_unitario" >= 0),
    CONSTRAINT "pk_detalle_pedidos" PRIMARY KEY ("id_detalle")
);

CREATE TABLE public."entregas" (
    "id_entrega" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_despacho" BIGINT NOT NULL,
    "fecha_entrega_real" TIMESTAMP WITHOUT TIME ZONE,
    "peso_entregado_kg" NUMERIC(12,2) DEFAULT 0.00 NOT NULL,
    "estado_entrega" VARCHAR(20) DEFAULT 'PENDIENTE' NOT NULL,
    "nombre_receptor" VARCHAR(120),
    "observaciones" TEXT,
    CONSTRAINT "chk_entrega_estado" CHECK ("estado_entrega" in ('PENDIENTE','COMPLETA','PARCIAL','RECHAZADA')),
    CONSTRAINT "chk_entrega_peso" CHECK ("peso_entregado_kg" >= 0),
    CONSTRAINT "pk_entregas" PRIMARY KEY ("id_entrega")
);

CREATE TABLE public."historial_estados_pedido" (
    "id_historial" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_pedido" BIGINT NOT NULL,
    "estado_anterior" VARCHAR(25),
    "estado_nuevo" VARCHAR(25) NOT NULL,
    "fecha_cambio" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "usuario_bd" VARCHAR(100),
    "observacion" VARCHAR(300),
    CONSTRAINT "pk_historial_estados_pedido" PRIMARY KEY ("id_historial")
);

CREATE TABLE public."municipios" (
    "id_municipio" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_municipio" VARCHAR(100) NOT NULL,
    "departamento" VARCHAR(100) DEFAULT 'Sucre' NOT NULL,
    CONSTRAINT "pk_municipios" PRIMARY KEY ("id_municipio"),
    CONSTRAINT "uk_municipio" UNIQUE ("nombre_municipio", "departamento")
);

CREATE TABLE public."novedades_relacionales" (
    "id_novedad" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_despacho" BIGINT,
    "id_entrega" BIGINT,
    "id_ruta" BIGINT,
    "tipo_novedad" VARCHAR(60) NOT NULL,
    "descripcion" TEXT NOT NULL,
    "fecha_novedad" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "minutos_retraso" BIGINT DEFAULT 0 NOT NULL,
    "responsable" VARCHAR(120),
    "estado_novedad" VARCHAR(20) DEFAULT 'ABIERTA' NOT NULL,
    CONSTRAINT "chk_novedad_asociacion" CHECK (("id_despacho" is not null) or ("id_entrega" is not null) or ("id_ruta" is not null)),
    CONSTRAINT "chk_novedad_estado" CHECK ("estado_novedad" in ('ABIERTA','EN_REVISION','RESUELTA')),
    CONSTRAINT "pk_novedades_relacionales" PRIMARY KEY ("id_novedad")
);

CREATE TABLE public."pedidos" (
    "id_pedido" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "numero_pedido" VARCHAR(30) NOT NULL,
    "id_cliente" BIGINT NOT NULL,
    "id_municipio_destino" BIGINT NOT NULL,
    "fecha_pedido" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "fecha_entrega_prometida" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "peso_total_kg" NUMERIC(12,2) DEFAULT 0.00 NOT NULL,
    "valor_total" NUMERIC(14,2) DEFAULT 0.00 NOT NULL,
    "estado_pedido" VARCHAR(25) DEFAULT 'PENDIENTE' NOT NULL,
    "observaciones" TEXT,
    CONSTRAINT "chk_pedido_estado" CHECK ("estado_pedido" in ('PENDIENTE','EN_PREPARACION','EN_TRANSITO','ENTREGADO','CANCELADO')),
    CONSTRAINT "chk_pedido_peso" CHECK ("peso_total_kg" >= 0),
    CONSTRAINT "chk_pedido_valor" CHECK ("valor_total" >= 0),
    CONSTRAINT "pk_pedidos" PRIMARY KEY ("id_pedido"),
    CONSTRAINT "uk_pedido_numero" UNIQUE ("numero_pedido")
);

CREATE TABLE public."productores" (
    "id_productor" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "tipo_documento" VARCHAR(15) NOT NULL,
    "numero_documento" VARCHAR(30) NOT NULL,
    "nombre_productor" VARCHAR(150) NOT NULL,
    "telefono" VARCHAR(25),
    "correo" VARCHAR(120),
    "direccion" VARCHAR(200),
    "id_municipio" BIGINT NOT NULL,
    "estado_productor" VARCHAR(15) DEFAULT 'ACTIVO' NOT NULL,
    CONSTRAINT "chk_productor_estado" CHECK ("estado_productor" in ('ACTIVO','INACTIVO')),
    CONSTRAINT "pk_productores" PRIMARY KEY ("id_productor"),
    CONSTRAINT "uk_productor_documento" UNIQUE ("tipo_documento", "numero_documento")
);

CREATE TABLE public."productos" (
    "id_producto" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "id_productor" BIGINT NOT NULL,
    "codigo_producto" VARCHAR(40) NOT NULL,
    "nombre_producto" VARCHAR(150) NOT NULL,
    "descripcion" TEXT,
    "unidad_medida" VARCHAR(30) NOT NULL,
    "peso_unitario_kg" NUMERIC(10,3) NOT NULL,
    "precio_unitario" NUMERIC(14,2) NOT NULL,
    "estado_producto" VARCHAR(15) DEFAULT 'ACTIVO' NOT NULL,
    CONSTRAINT "chk_producto_estado" CHECK ("estado_producto" in ('ACTIVO','INACTIVO')),
    CONSTRAINT "chk_producto_peso" CHECK ("peso_unitario_kg" > 0),
    CONSTRAINT "chk_producto_precio" CHECK ("precio_unitario" >= 0),
    CONSTRAINT "pk_productos" PRIMARY KEY ("id_producto"),
    CONSTRAINT "uk_producto_codigo" UNIQUE ("codigo_producto")
);

CREATE TABLE public."rutas" (
    "id_ruta" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_ruta" VARCHAR(120) NOT NULL,
    "id_municipio_origen" BIGINT NOT NULL,
    "id_municipio_destino" BIGINT NOT NULL,
    "distancia_km" NUMERIC(10,2),
    "tiempo_estimado_horas" NUMERIC(8,2),
    "descripcion" TEXT,
    "estado_ruta" VARCHAR(15) DEFAULT 'ACTIVA' NOT NULL,
    CONSTRAINT "chk_ruta_distancia" CHECK (("distancia_km" is null) or ("distancia_km" > 0)),
    CONSTRAINT "chk_ruta_estado" CHECK ("estado_ruta" in ('ACTIVA','INACTIVA')),
    CONSTRAINT "chk_ruta_tiempo" CHECK (("tiempo_estimado_horas" is null) or ("tiempo_estimado_horas" > 0)),
    CONSTRAINT "pk_rutas" PRIMARY KEY ("id_ruta")
);

CREATE TABLE public."tipos_vehiculo" (
    "id_tipo_vehiculo" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre_tipo" VARCHAR(60) NOT NULL,
    "descripcion" VARCHAR(200),
    CONSTRAINT "pk_tipos_vehiculo" PRIMARY KEY ("id_tipo_vehiculo"),
    CONSTRAINT "uk_tipo_vehiculo_nombre" UNIQUE ("nombre_tipo")
);

CREATE TABLE public."vehiculos" (
    "id_vehiculo" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "placa" VARCHAR(10) NOT NULL,
    "id_tipo_vehiculo" BIGINT NOT NULL,
    "marca" VARCHAR(60),
    "modelo" VARCHAR(60),
    "anio" SMALLINT,
    "capacidad_carga_kg" NUMERIC(12,2) NOT NULL,
    "estado_vehiculo" VARCHAR(25) DEFAULT 'DISPONIBLE' NOT NULL,
    CONSTRAINT "chk_vehiculo_capacidad" CHECK ("capacidad_carga_kg" > 0),
    CONSTRAINT "chk_vehiculo_estado" CHECK ("estado_vehiculo" in ('DISPONIBLE','EN_RUTA','EN_MANTENIMIENTO','FUERA_DE_SERVICIO')),
    CONSTRAINT "pk_vehiculos" PRIMARY KEY ("id_vehiculo"),
    CONSTRAINT "uk_vehiculo_placa" UNIQUE ("placa")
);

-- Claves foraneas separadas para resolver el orden de creacion de tablas.
ALTER TABLE public."auditoria_despachos" ADD CONSTRAINT "fk_auditoria_despacho" FOREIGN KEY ("id_despacho") REFERENCES public."despachos_asignaciones" ("id_despacho") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."clientes" ADD CONSTRAINT "fk_cliente_municipio" FOREIGN KEY ("id_municipio") REFERENCES public."municipios" ("id_municipio") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."despachos_asignaciones" ADD CONSTRAINT "fk_despacho_conductor" FOREIGN KEY ("id_conductor") REFERENCES public."conductores" ("id_conductor") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."despachos_asignaciones" ADD CONSTRAINT "fk_despacho_pedido" FOREIGN KEY ("id_pedido") REFERENCES public."pedidos" ("id_pedido") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."despachos_asignaciones" ADD CONSTRAINT "fk_despacho_ruta" FOREIGN KEY ("id_ruta") REFERENCES public."rutas" ("id_ruta") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."despachos_asignaciones" ADD CONSTRAINT "fk_despacho_vehiculo" FOREIGN KEY ("id_vehiculo") REFERENCES public."vehiculos" ("id_vehiculo") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."detalle_pedidos" ADD CONSTRAINT "fk_detalle_pedido" FOREIGN KEY ("id_pedido") REFERENCES public."pedidos" ("id_pedido") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."detalle_pedidos" ADD CONSTRAINT "fk_detalle_producto" FOREIGN KEY ("id_producto") REFERENCES public."productos" ("id_producto") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."entregas" ADD CONSTRAINT "fk_entrega_despacho" FOREIGN KEY ("id_despacho") REFERENCES public."despachos_asignaciones" ("id_despacho") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."historial_estados_pedido" ADD CONSTRAINT "fk_historial_pedido" FOREIGN KEY ("id_pedido") REFERENCES public."pedidos" ("id_pedido") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."novedades_relacionales" ADD CONSTRAINT "fk_novedad_despacho" FOREIGN KEY ("id_despacho") REFERENCES public."despachos_asignaciones" ("id_despacho") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE public."novedades_relacionales" ADD CONSTRAINT "fk_novedad_entrega" FOREIGN KEY ("id_entrega") REFERENCES public."entregas" ("id_entrega") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE public."novedades_relacionales" ADD CONSTRAINT "fk_novedad_ruta" FOREIGN KEY ("id_ruta") REFERENCES public."rutas" ("id_ruta") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE public."pedidos" ADD CONSTRAINT "fk_pedido_cliente" FOREIGN KEY ("id_cliente") REFERENCES public."clientes" ("id_cliente") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."pedidos" ADD CONSTRAINT "fk_pedido_municipio" FOREIGN KEY ("id_municipio_destino") REFERENCES public."municipios" ("id_municipio") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."productores" ADD CONSTRAINT "fk_productor_municipio" FOREIGN KEY ("id_municipio") REFERENCES public."municipios" ("id_municipio") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."productos" ADD CONSTRAINT "fk_producto_productor" FOREIGN KEY ("id_productor") REFERENCES public."productores" ("id_productor") ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE public."rutas" ADD CONSTRAINT "fk_ruta_destino" FOREIGN KEY ("id_municipio_destino") REFERENCES public."municipios" ("id_municipio") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE public."rutas" ADD CONSTRAINT "fk_ruta_origen" FOREIGN KEY ("id_municipio_origen") REFERENCES public."municipios" ("id_municipio") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE public."vehiculos" ADD CONSTRAINT "fk_vehiculo_tipo" FOREIGN KEY ("id_tipo_vehiculo") REFERENCES public."tipos_vehiculo" ("id_tipo_vehiculo") ON UPDATE CASCADE ON DELETE RESTRICT;

COMMIT;

-- Verificar tablas (deben ser 15):
SELECT COUNT(*) AS tablas FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE';
-- Verificar claves foraneas (deben ser 20):
SELECT COUNT(*) AS claves_foraneas FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='public' AND c.contype='f';
-- Verificar restricciones CHECK:
SELECT COUNT(*) AS checks FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='public' AND c.contype='c';
-- Verificar columna generada:
SELECT column_name, is_generated, generation_expression FROM information_schema.columns WHERE table_schema='public' AND table_name='detalle_pedidos' AND column_name='subtotal';
